action.code:
size_t hashes[2];
ckh->hash(key, hashes);
size_t bucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
size_t cell = ckh_bucket_search(ckh, bucket, key);
if (cell != SIZE_T_MAX) {
    return cell;
}
bucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);
cell = ckh_bucket_search(ckh, bucket, key);
return cell;

